        QueueHandle_t xQueueHandle1 = NULL, xQueueHandle2 = NULL, xReceivedHandle = NULL;
        const UBaseType_t xLengthOfOne = ( UBaseType_t ) 1;

        /* Create two queues that have a length of one - a requirement in order to call
